DeviceProperties.ReadScriptPacketParser:
IF isOnline = 0
    ADDWARNING("Device is offline (MQTT LWT)");
END

DeviceProperties.ListenerScriptPacketParser:
IF(plugTopic = "shellies/shellyplug-s-gen3")
    ADDERROR("Set correct 'plugTopic' value in module variables. It is the MQTT prefix from 'http://shellyIpAddress' -> Settings -> Connectivity -> MQTT, by default 'shellyplugsg3-<deviceid>', but it may be a custom multi-level prefix such as 'shellies/shellyplug-s-kitchen'.");
    RETURN(-1);
END

# The root topic may cover several devices (e.g. shellies/#), so every topic is
# compared against the full prefix of this device - other Shellys are ignored.

# Device availability (MQTT last will)
IF(RECEIVEDMSG.TOPIC = plugTopic + "/online")
    isOnline := IF(TOSTRING(RECEIVEDMSG.PAYLOAD) = "true", 1, 0);
END

# Full status snapshot - published when "Generic status update over MQTT" is enabled
IF(RECEIVEDMSG.TOPIC = plugTopic + "/status/switch:0")
    internalTemp := PARSEJSON(RECEIVEDMSG.PAYLOAD, "temperature.tC");
    voltage := PARSEJSON(RECEIVEDMSG.PAYLOAD, "voltage");
    current := PARSEJSON(RECEIVEDMSG.PAYLOAD, "current");

    VAR errors := PARSEJSON(RECEIVEDMSG.PAYLOAD, "errors", TRUE);
    IF (!ISNULL(errors))
        VAR errCount := LENGTH(errors);
        VAR i := 0;
        VAR errorText := "";

        WHILE i < errCount
            IF LENGTH(errorText)
                errorText += ", ";
            END
            errorText := errorText + GETAT(errors, i);
            i += 1;
        LOOP

        IF LENGTH(errorText)
            ADDERROR(errorText);
        END
    END
END

# Incremental RPC notifications (NotifyStatus / NotifyFullStatus) - only changed keys are present
IF(RECEIVEDMSG.TOPIC = plugTopic + "/events/rpc")
    VAR t := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].temperature.tC", TRUE);
    IF(!ISNULL(t), internalTemp := t);
    VAR v := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].voltage", TRUE);
    IF(!ISNULL(v), voltage := v);
    VAR a := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].current", TRUE);
    IF(!ISNULL(a), current := a);
END

IF(RECEIVEDMSG.TOPIC = plugTopic + "/status/switch:0")
    St := IF(PARSEJSON(RECEIVEDMSG.PAYLOAD, "output"), 1, 0);
END

IF(RECEIVEDMSG.TOPIC = plugTopic + "/events/rpc")
    VAR output := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].output", TRUE);
    IF(!ISNULL(output), St := IF(output, 1, 0));
END

DeviceProperties.WriteSwitchStateScriptPacketParser:
# RPC over MQTT - enabled by default on Gen3 devices
VAR rpc := "{\"id\":1,\"src\":\"taphome\",\"method\":\"Switch.Set\",\"params\":{\"id\":0,\"on\":" + IF(St = 1, "true", "false") + "}}";
MQTTPUBLISH(plugTopic + "/rpc", rpc);

# Alternative, only works when Settings -> MQTT -> "Enable MQTT Control" is ticked:
# MQTTPUBLISH(plugTopic + "/command/switch:0", IF(St = 1, "on", "off"));

DeviceProperties.ListenerScriptPacketParser:
IF(RECEIVEDMSG.TOPIC = plugTopic + "/status/switch:0")
    Ed := PARSEJSON(RECEIVEDMSG.PAYLOAD, "apower") / 1000.0;
    To := PARSEJSON(RECEIVEDMSG.PAYLOAD, "aenergy.total") / 1000.0;
END

IF(RECEIVEDMSG.TOPIC = plugTopic + "/events/rpc")
    VAR apower := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].apower", TRUE);
    IF(!ISNULL(apower), Ed := apower / 1000.0);
    VAR total := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].aenergy.total", TRUE);
    IF(!ISNULL(total), To := total / 1000.0);
END
